using Microsoft.AspNetCore.DataProtection;
using Microsoft.EntityFrameworkCore;
using System.Net.Http.Headers;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
namespace Society.Api;

public class FinanceGateway(IHttpClientFactory factory,IDataProtectionProvider protection,IConfiguration config,IHostEnvironment env){
 public bool TestAllowed=>env.IsDevelopment()&&config.GetValue<bool>("Finance:AllowTestGateway");
 public string Protect(string value)=>protection.CreateProtector("assemblia.finance.secrets.v1").Protect(value);
 public JsonObject Secrets(PaymentConnection p)=>MembershipService.Json(protection.CreateProtector("assemblia.finance.secrets.v1").Unprotect(p.ProtectedSecrets));
 public HttpClient Client(PaymentConnection p){var c=factory.CreateClient("finance");c.Timeout=TimeSpan.FromSeconds(20);c.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Basic",Convert.ToBase64String(Encoding.UTF8.GetBytes(p.PublicKey+":"+Secrets(p)["secret"])));return c;}
 public async Task<bool> Verify(PaymentConnection p,CancellationToken ct){if(p.Provider=="Test")return TestAllowed;if(p.Provider!="Razorpay"||p.Mode=="Test"&&!p.PublicKey.StartsWith("rzp_test_")||p.Mode=="Live"&&!p.PublicKey.StartsWith("rzp_live_"))return false;using var client=Client(p);using var response=await client.GetAsync("https://api.razorpay.com/v1/orders?count=1",ct);return response.IsSuccessStatusCode;}
 public async Task<string> Order(PaymentConnection p,PaymentIntent intent,CancellationToken ct){if(p.Provider=="Test"){if(!TestAllowed)throw new DomainException("Test gateway is disabled");return "testorder_"+intent.Id.ToString("N");}if(p.Provider!="Razorpay")throw new DomainException("No supported payment adapter");using var client=Client(p);var amount=checked((long)(intent.Amount*FinanceService.MinorFactor(intent.Currency)));using var response=await client.PostAsJsonAsync("https://api.razorpay.com/v1/orders",new{amount,currency=intent.Currency,receipt=intent.Id.ToString("N"),notes=new{intent_id=intent.Id.ToString()}},ct);if(!response.IsSuccessStatusCode)throw new DomainException("Provider order creation failed; reconcile this attempt before retrying");var json=JsonNode.Parse(await response.Content.ReadAsStringAsync(ct))!;if(json["amount"]?.GetValue<long>()!=amount||json["currency"]?.ToString()!=intent.Currency)throw new DomainException("Provider returned an inconsistent order");return json["id"]?.ToString()??throw new DomainException("Provider returned no order reference");}
 public async Task<string> Refund(PaymentConnection p,FinancePayment payment,FinanceRefund refund,CancellationToken ct){if(p.Provider=="Test"){if(!TestAllowed)throw new DomainException("Test gateway is disabled");return "testrefund_"+refund.Id.ToString("N");}using var client=Client(p);var amount=checked((long)(refund.Amount*FinanceService.MinorFactor(refund.Currency)));using var response=await client.PostAsJsonAsync("https://api.razorpay.com/v1/payments/"+Uri.EscapeDataString(payment.ProviderReference!)+"/refund",new{amount,receipt=refund.Id.ToString("N"),notes=new{refund_id=refund.Id.ToString()}},ct);if(!response.IsSuccessStatusCode)throw new DomainException("Provider refund response is uncertain; reconcile before repeating");var node=JsonNode.Parse(await response.Content.ReadAsStringAsync(ct))!;return node["id"]?.ToString()??throw new DomainException("Provider returned no refund reference");}
}
public static partial class FinanceEndpoints {
 static IQueryable<Guid> ProviderAncestors(AppDb db,Guid tenant,Guid? unit)=>db.Units.FromSqlInterpolated($"WITH RECURSIVE chain AS (SELECT * FROM \"Units\" WHERE \"TenantId\"={tenant} AND \"Id\"={unit} UNION ALL SELECT p.* FROM \"Units\" p JOIN chain child ON child.\"ParentId\"=p.\"Id\" WHERE p.\"TenantId\"={tenant}) SELECT * FROM chain").Select(u=>u.Id);
 static void MapPayments(RouteGroupBuilder t){
 t.MapGet("/providers",async(Guid tenant,Guid? entity,FinanceService s)=>await s.Scoped<PaymentConnection>(tenant,"finance.providers",entity).Select(p=>new{p.Id,p.EntityId,p.UnitId,p.Name,p.Provider,p.PublicKey,p.Mode,p.Enabled,p.Verified,p.Health,p.CheckedAt}).ToListAsync());
 t.MapPost("/providers",async(Guid tenant,ProviderWrite r,AppDb db,Access a,FinanceService s,FinanceGateway gateway)=>{await s.Require(tenant,r.EntityId,r.UnitId,"finance.providers");if(r.Provider is not("Razorpay" or "Test")||r.Provider=="Test"&&!gateway.TestAllowed||r.Mode is not("Test" or "Live")||r.Name.Length is <2 or >160||r.PublicKey.Length>180||r.Secrets.Length>5000)throw new DomainException("Choose an available provider, mode and account name");var secret=MembershipService.Json(r.Secrets);if(secret["secret"]?.ToString().Length<16||secret["webhookSecret"]?.ToString().Length<16)throw new DomainException("Configure complete API and webhook secrets");var connection=new PaymentConnection{TenantId=tenant,EntityId=r.EntityId,UnitId=r.UnitId,Name=r.Name,Provider=r.Provider,PublicKey=r.PublicKey,Mode=r.Mode,ProtectedSecrets=gateway.Protect(r.Secrets),Enabled=r.Enabled};db.Add(connection);a.Audit(tenant,"finance.provider.configured",connection.Id,new{r.Provider,r.Mode});await db.SaveChangesAsync();return Results.Ok(new{connection.Id,connection.Name,connection.Verified});});
 t.MapPost("/providers/{id:guid}/verify",async(Guid tenant,Guid id,AppDb db,Access a,FinanceService s,FinanceGateway gateway,CancellationToken ct)=>{var p=await db.Set<PaymentConnection>().SingleOrDefaultAsync(p=>p.TenantId==tenant&&p.Id==id)??throw new AccessDeniedException();await s.Require(tenant,p.EntityId,p.UnitId,"finance.providers");try{p.Verified=await gateway.Verify(p,ct);p.Health=p.Verified?"API authentication verified; webhook and live settlement require separate acceptance tests":"Verification failed";}catch{p.Verified=false;p.Health="Provider verification unavailable";}p.CheckedAt=DateTimeOffset.UtcNow;a.Audit(tenant,"finance.provider.verified",id,new{p.Verified});await db.SaveChangesAsync();return Results.Ok(new{p.Verified,p.Health});});
 t.MapPost("/providers/{id:guid}/disable",async(Guid tenant,Guid id,AppDb db,Access a,FinanceService s)=>{var p=await db.Set<PaymentConnection>().SingleOrDefaultAsync(p=>p.TenantId==tenant&&p.Id==id)??throw new AccessDeniedException();await s.Require(tenant,p.EntityId,p.UnitId,"finance.providers");p.Enabled=false;p.Verified=false;p.Health="Disabled";a.Audit(tenant,"finance.provider.disabled",id);await db.SaveChangesAsync();return Results.NoContent();});
 t.MapPost("/invoices/{id:guid}/payment-intents",async(Guid tenant,Guid id,IntentWrite r,AppDb db,Access a,FinanceService s,FinanceGateway gateway,CancellationToken ct)=>{PaymentIntent intent;PaymentConnection connection;await using(var tx=await db.Database.BeginTransactionAsync(ct)){await FinanceService.Lock(db,tenant);var i=await s.Invoice(tenant,id);if(!await s.Own(i))await s.Require(tenant,i.EntityId,i.UnitId,"finance.collect");if(i.Status!="Issued"||i.Kind!="Invoice"||i.Total-i.Paid-i.Credited<=0||r.Key.Length is <3 or >100)throw new DomainException("Choose an issued outstanding invoice and stable checkout key");var old=await db.Set<PaymentIntent>().SingleOrDefaultAsync(p=>p.TenantId==tenant&&p.UserId==a.UserId&&p.Key==r.Key,ct);if(old!=null){if(old.InvoiceId!=id)throw new DomainException("Checkout key belongs to another invoice");return Results.Ok(new{intent=old,publicKey=await db.Set<PaymentConnection>().Where(c=>c.Id==old.ConnectionId).Select(c=>c.PublicKey).SingleAsync(ct)});}var allowedProviderUnits=ProviderAncestors(db,tenant,i.UnitId);connection=await db.Set<PaymentConnection>().SingleOrDefaultAsync(c=>c.TenantId==tenant&&c.EntityId==i.EntityId&&c.Id==r.ConnectionId&&c.Enabled&&c.Verified&&(c.UnitId==null||allowedProviderUnits.Contains(c.UnitId.Value)),ct)??throw new DomainException("No verified, enabled provider for this invoice");intent=new(){TenantId=tenant,EntityId=i.EntityId,UnitId=i.UnitId,InvoiceId=id,ConnectionId=connection.Id,UserId=a.UserId,Amount=i.Total-i.Paid-i.Credited,Currency=i.Currency,Key=r.Key};db.Add(intent);await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);}try{intent.OrderId=await gateway.Order(connection,intent,ct);intent.Status="Created";}catch(Exception ex)when(ex is HttpRequestException or TaskCanceledException or DomainException){intent.Status="Unknown";await db.SaveChangesAsync(CancellationToken.None);throw new DomainException("Checkout creation needs reconciliation before another attempt");}await db.SaveChangesAsync(ct);return Results.Ok(new{intent,publicKey=connection.PublicKey,provider=connection.Provider,mode=connection.Mode});});
 t.MapGet("/invoices/{id:guid}/checkout-options",async(Guid tenant,Guid id,AppDb db,FinanceService s)=>{var i=await s.Invoice(tenant,id);var units=ProviderAncestors(db,tenant,i.UnitId);return await db.Set<PaymentConnection>().Where(p=>p.TenantId==tenant&&p.EntityId==i.EntityId&&p.Enabled&&p.Verified&&(p.UnitId==null||units.Contains(p.UnitId.Value))).Select(p=>new{p.Id,p.Name,p.Provider,p.PublicKey,p.Mode}).ToListAsync();});
 t.MapGet("/refunds",async(Guid tenant,Guid? entity,FinanceService s)=>await s.Scoped<FinanceRefund>(tenant,entity:entity).OrderByDescending(r=>r.At).Take(100).ToListAsync());
 t.MapPost("/refunds/{id:guid}/decision",async(Guid tenant,Guid id,FinanceDecision r,AppDb db,Access a,FinanceService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await FinanceService.Lock(db,tenant);var x=await db.Set<FinanceRefund>().SingleOrDefaultAsync(x=>x.TenantId==tenant&&x.Id==id&&x.Status=="Pending Approval")??throw new AccessDeniedException();var p=await db.Set<FinancePayment>().SingleAsync(p=>p.TenantId==tenant&&p.Id==x.PaymentId);var e=await s.Require(tenant,x.EntityId,x.UnitId,"finance.refund");await s.Review(tenant,id,x.AuthorId,x.UnitId!.Value,"FinanceRefund",r,x.Amount,e);if(r.Decision=="Approve"){x.ApprovedBy=a.UserId;if(p.ProviderId!=null)x.Status="Approved";else await s.CompleteRefund(x,p,e,a.UserId);}else x.Status="Rejected";await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(x);});
 t.MapPost("/refunds/{id:guid}/dispatch",async(Guid tenant,Guid id,AppDb db,Access a,FinanceService s,FinanceGateway gateway,CancellationToken ct)=>{FinanceRefund x;FinancePayment p;PaymentConnection provider;await using(var tx=await db.Database.BeginTransactionAsync(ct)){await FinanceService.Lock(db,tenant);x=await db.Set<FinanceRefund>().SingleOrDefaultAsync(x=>x.TenantId==tenant&&x.Id==id&&x.Status=="Approved",ct)??throw new AccessDeniedException();await s.Require(tenant,x.EntityId,x.UnitId,"finance.refund");if(x.AuthorId==a.UserId)throw new AccessDeniedException();p=await db.Set<FinancePayment>().SingleAsync(p=>p.TenantId==tenant&&p.Id==x.PaymentId,ct);if(x.Amount>p.Amount-p.Refunded-p.ChargedBack)throw new DomainException("Refund is no longer available after a prior return or dispute");provider=await db.Set<PaymentConnection>().SingleAsync(c=>c.Id==p.ProviderId&&c.TenantId==tenant&&c.Enabled&&c.Verified,ct);x.Status="Processing";x.ProcessingAt=DateTimeOffset.UtcNow;await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);}try{x.ProviderReference=await gateway.Refund(provider,p,x,ct);if(provider.Provider=="Test"){await using var tx=await db.Database.BeginTransactionAsync(ct);await FinanceService.Lock(db,tenant);var e=await db.Set<FinancialEntity>().SingleAsync(e=>e.Id==x.EntityId,ct);await s.CompleteRefund(x,p,e,x.ApprovedBy!.Value,x.ProviderReference);await tx.CommitAsync(ct);}else x.Status="Awaiting Provider";}catch{x.Status="Unknown";}await db.SaveChangesAsync(CancellationToken.None);return Results.Ok(new{x.Id,x.Status,x.ProviderReference});});
 }
 public static void MapPaymentWebhooks(RouteGroupBuilder api){api.MapPost("/finance/webhooks/{id:guid}",async(Guid id,HttpRequest request,AppDb db,FinanceGateway gateway,FinanceService s,Access a)=>{var c=await db.Set<PaymentConnection>().SingleOrDefaultAsync(c=>c.Id==id)??throw new AccessDeniedException();if(c.Provider=="Test"&&!gateway.TestAllowed)throw new AccessDeniedException();if(request.ContentLength is null or >1048576)throw new DomainException("Bounded webhook body required");using var output=new MemoryStream();await request.Body.CopyToAsync(output);var body=output.ToArray();if(body.Length>1048576)throw new DomainException("Webhook too large");var secret=gateway.Secrets(c)["webhookSecret"]?.ToString()??"";var expected=Convert.ToHexString(HMACSHA256.HashData(Encoding.UTF8.GetBytes(secret),body)).ToLowerInvariant();var signature=request.Headers["X-Razorpay-Signature"].ToString();if(secret.Length<16||!CommunicationProviders.Fixed(signature,expected))throw new AccessDeniedException();var eventKey=request.Headers["X-Razorpay-Event-Id"].ToString();if(eventKey.Length is <3 or >200)throw new DomainException("Stable provider event ID required");var json=JsonNode.Parse(body)!;var kind=json["event"]?.ToString()??"";await using var tx=await db.Database.BeginTransactionAsync();await FinanceService.Lock(db,c.TenantId);if(await db.Set<FinanceProviderEvent>().AnyAsync(e=>e.ConnectionId==id&&e.EventKey==eventKey))return Results.Ok(new{duplicate=true});db.Add(new FinanceProviderEvent{TenantId=c.TenantId,EntityId=c.EntityId,UnitId=c.UnitId,ConnectionId=id,EventKey=eventKey,Kind=kind,Hash=CommunityService.Hash(Encoding.UTF8.GetString(body))});
 if(kind=="payment.captured"){var node=json["payload"]?["payment"]?["entity"]??throw new DomainException("Missing captured payment");var order=node["order_id"]?.ToString()??"";var reference=node["id"]?.ToString()??"";var intent=await db.Set<PaymentIntent>().SingleOrDefaultAsync(i=>i.TenantId==c.TenantId&&i.EntityId==c.EntityId&&i.ConnectionId==id&&i.OrderId==order);if(intent==null&&Guid.TryParse(node["notes"]?["intent_id"]?.ToString(),out var intentId)){intent=await db.Set<PaymentIntent>().SingleOrDefaultAsync(i=>i.Id==intentId&&i.TenantId==c.TenantId&&i.EntityId==c.EntityId&&i.ConnectionId==id&&i.OrderId==null);if(intent!=null)intent.OrderId=order;}if(intent==null)throw new DomainException("Payment order does not match a local intent");var currency=node["currency"]?.ToString()??"";var amount=node["amount"]?.GetValue<decimal>()??-1;var expectedMinor=intent.Amount*FinanceService.MinorFactor(intent.Currency);if(amount!=expectedMinor||currency!=intent.Currency||node["status"]?.ToString()!="captured"||reference.Length is <3 or >200)throw new DomainException("Captured amount, currency or state does not match order");var existing=await db.Set<FinancePayment>().SingleOrDefaultAsync(p=>p.TenantId==c.TenantId&&p.ProviderId==id&&p.ProviderReference==reference);if(existing==null&&intent.PaymentId==null){var invoice=await db.Set<FinanceInvoice>().SingleAsync(i=>i.TenantId==c.TenantId&&i.Id==intent.InvoiceId);var entity=await db.Set<FinancialEntity>().SingleAsync(e=>e.TenantId==c.TenantId&&e.Id==c.EntityId&&e.Active);var payment=new FinancePayment{TenantId=c.TenantId,EntityId=c.EntityId,UnitId=invoice.UnitId,AuthorId=intent.UserId,MembershipId=invoice.MembershipId,PayerUnitId=invoice.BilledUnitId,DonorId=invoice.DonorId,Payer=invoice.CounterpartyName,Reference="gateway:"+reference,ProviderId=id,ProviderReference=reference,Amount=intent.Amount,Currency=currency,Method="Gateway",Date=FinanceService.Today};db.Add(payment);await s.Confirm(payment,entity,null,true);intent.PaymentId=payment.Id;intent.Status="Captured";var allocation=Math.Min(payment.Amount,Math.Max(0,invoice.Total-invoice.Paid-invoice.Credited));if(invoice.Status=="Issued"&&allocation>0)await s.Allocate(payment,invoice,allocation,"gateway-allocation:"+reference,intent.UserId);}}
 else if(kind=="payment.dispute.lost"){var node=json["payload"]?["dispute"]?["entity"]??throw new DomainException("Missing dispute evidence");var reference=node["id"]?.ToString()??"";var paymentRef=node["payment_id"]?.ToString();var payment=await db.Set<FinancePayment>().SingleOrDefaultAsync(p=>p.TenantId==c.TenantId&&p.EntityId==c.EntityId&&p.ProviderId==id&&p.ProviderReference==paymentRef)??throw new DomainException("Disputed payment is unknown");if(node["status"]?.ToString()!="lost"||node["currency"]?.ToString()!=payment.Currency||reference.Length is <3 or >160)throw new DomainException("Dispute status or currency does not match");var amount=(node["amount_deducted"]?.GetValue<decimal>()??node["amount"]?.GetValue<decimal>()??0)/FinanceService.MinorFactor(payment.Currency);var key="chargeback:"+reference;if(!await db.Set<FinanceRefund>().AnyAsync(r=>r.TenantId==c.TenantId&&r.EntityId==c.EntityId&&r.Reference==key)){var refund=new FinanceRefund{TenantId=c.TenantId,EntityId=c.EntityId,UnitId=payment.UnitId,PaymentId=payment.Id,AuthorId=payment.AuthorId,Kind="Chargeback",Reference=key,Reason="Verified provider dispute lost",Amount=amount,Currency=payment.Currency,Date=FinanceService.Today,ProviderReference=reference};db.Add(refund);var entity=await db.Set<FinancialEntity>().SingleAsync(e=>e.Id==c.EntityId);await s.CompleteRefund(refund,payment,entity,payment.AuthorId,reference);}}
 else if(kind=="refund.processed"){var node=json["payload"]?["refund"]?["entity"]??throw new DomainException("Missing refund entity");var reference=node["id"]?.ToString()??"";var refund=await db.Set<FinanceRefund>().SingleOrDefaultAsync(x=>x.TenantId==c.TenantId&&x.EntityId==c.EntityId&&x.ProviderReference==reference)??throw new DomainException("Refund reference is not recognized");var payment=await db.Set<FinancePayment>().SingleAsync(p=>p.Id==refund.PaymentId&&p.ProviderId==id);if(node["payment_id"]?.ToString()!=payment.ProviderReference||node["amount"]?.GetValue<decimal>()!=refund.Amount*FinanceService.MinorFactor(refund.Currency))throw new DomainException("Refund amount/payment mismatch");var entity=await db.Set<FinancialEntity>().SingleAsync(e=>e.Id==c.EntityId);if(refund.Status!="Processed")await s.CompleteRefund(refund,payment,entity,refund.ApprovedBy!.Value,reference);}
 await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(new{received=true});}).RequireRateLimiting("community");}
}
public record ProviderWrite(Guid EntityId,Guid UnitId,string Name,string Provider,string PublicKey,string Secrets,string Mode="Test",bool Enabled=false);
public record IntentWrite(Guid ConnectionId,string Key);
